--- Start
---@param rowData TableML.TableFileRow 功能分割表
function MaidCoffeeDriver:Start(exParams)
    local autoData = { }
    if not isNull(exParams) then
        local id = nil
        if isSet(exParams,"id") and exParams.id ~= "" then
            id = exParams.id
        end
        autoData = {id = id , data = not isNull(exParams.data) and exParams.data or nil}
    end
    self:EnterMapDecryptionPanel(autoData, false)
end

function MaidCoffeeDriver:EnterMapDecryptionPanel(autoData, isPlayOp)
    local parameters = {
        autoData = autoData,
        isPlayOp = isPlayOp,
        luaPath      = "Game.MaidCoffee.MaidCoffeeSceneEnter",
    }
    KCookie.Set(Constants.UICacheDataKeys.OVERSEA_MANAGER_SCENE_STATE, 1)
    --GameUtils.OpenLoadingPanel(UIArgs(Constants.UITypeIds.UIMaidCoffeeEnterScene, parameters), { UIArgs(Constants.UITypeIds.UIMaidCoffeeMainDialog, parameters) }, Constants.LoadingType.Others, false)
    self:StartBlackEnter(parameters)
end

function MaidCoffeeDriver:StartBlackEnter(parameters)
    self._isLoadSuccess = false
    self.loadCafeCo = cs_coroutine.start(function()
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
        self.args = UIArgs(Constants.UITypeIds.UIMaidCoffeeEnterScene, parameters)
        self.args.hasExcluded = false
        self.dialogArgs = { UIArgs(Constants.UITypeIds.UIMaidCoffeeMainDialog, parameters) }
        if UIModule.CurrentScreen then
            UIModule.CurrentScreen.Argument = clone(checkTable(self.args))
        end

        local time = GameUtils.ShowBlackOverlay(nil, function()
            while not self._isLoadSuccess do
                coroutine.yield(Yielders.EndOfFrame)
            end
        end)
        --等屏幕黑了再开始加载  要不ka
        coroutine.yield(WaitForSeconds(time))
        coroutine.yield(WaitForSeconds(0.2))
        ---场景设置信息
        CS.UnityEngine.Application.backgroundLoadingPriority = CS.UnityEngine.ThreadPriority.High
        UINavigationBarRoot.Instance:SetActive(false)

        ---去战斗的情况
        UIModule.StoreStackState(self.args)
        ---关闭所有的窗口
        xTry(function()
            local needWaitDialogClose = false
            local coWait = CoWait.Start()
            for i, v in support.list_ipairs(UIModule.CurrentScreen.dialogs) do
                local isRemove = string.isEmpty(v.Argument.extra)
                local coClose = UIModule.CloseDialog(v, isRemove)
                if not isNull(coClose) then
                    needWaitDialogClose = true
                    coWait:Coroutine(coClose)
                end
            end
            UIModule.CurrentScreen.dialogs:Clear()
            while needWaitDialogClose and not coWait.IsFinish do
                coroutine.yield()
            end
        end)
        ---开始加载战斗场景
        xpcall(function()
            KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, false)
            if self.args then
                cs_coroutine.yield_return(UIModule.OpenScreen(self.args, true))
                ---@type MaidCoffeeEntry
                local env = UIModule.CurrentScreen.Env
                cs_coroutine.yield_return(env:AsyncLoadingResources())
                cs_coroutine.yield_return(UIModule.OpenDialog(UIArgs(Constants.UITypeIds.UIMaidCoffeeMainDialog, parameters) ))

                self._isLoadSuccess = true
            end
        end, function(err)
            print(err)
            printError(tostring(err))
        end)

    end)

end

return MaidCoffeeDriver
